  PERFORM coaching.apply_candidate_exercise_card_v1($card_1_payload${"migrationKey":"718_coaching_falling_start_hold_source_98_candidate_materialization","researchVersion":"2026-07-25.11","definition":{"facilityId":1,"legacyExerciseId":98,"preserveLegacyExerciseId":true,"slug":"falling-start-hold","canonicalName":"Falling Start Position Hold","displayName":"Falling Start Position Hold","aliases":["Falling Start Hold","Fall-to-Split-Stance Hold","Falling Start Catch and Hold"],"description":"From a tall stationary stance in a clear, level, non-slip zone, lean forward as one aligned body until one recovery step is required. Recover with exactly one step, catch a stable split stance, and hold the terminal position before a controlled reset. Alternate intended lead legs. One repetition is one controlled lean, one recovery step, quiet split-stance catch, declared hold, and reset. This is not a sprint, multi-step falling catch, wall lean, reactive release, start test, or acceleration drill.","familyKey":"forward_fall_single_step_catch_hold","schemaVersion":"2.0.0","cardVersion":3,"status":"review","identityContract":"stationary_aligned_forward_lean_to_exactly_one_recovery_step_stable_split_stance_catch_declared_hold_and_reset_without_sprinting","confidence":{"content":74,"scoring":48,"media":38},"movementPatterns":["project","controlled_deceleration","stabilize"],"bodyRegions":["foot","ankle","calf","knee","thigh","hip","core","upper_arm"],"requiredEquipment":["none"],"optionalEquipment":["floor_marks","video","wall_optional"],"environment":{"surface":"clear, level, dry, non-slip, impact-appropriate catch zone","space":"one protected forward fall-and-catch zone with clear reset path and no cross traffic","stationCapacity":1,"inspection":["surface traction, debris, moisture, and forward clearance","visible start and catch zone","footwear, communication, exit, and coach sightline"],"changeRule":"Changing lean threshold, recovery-step count, lead side, hold, support, cue, su