ationQuarantined":true},"deliveryProfiles":[{"key":"movement-intelligence-falling-start-hold","phase":"movement_intelligence","role":"conditional","purpose":"Candidate no-sprint forward-fall initiation-control and split-stance catch practice.","suitability":64,"methodologyAlignment":56,"objectiveRelevance":{"initiation_control":70,"split_stance_stability":62},"dosage":{"sets":"2-4","attemptsPerLeadSide":"2-4","holdSeconds":"2-4","restSeconds":"20-60","intensity":"controlled_lean_not_maximal","countRule":"count only an aligned forward lean, exactly one recovery step, quiet stable split-stance catch, declared hold, and reset without sprint"},"qualityGate":"The athlete stays aligned into the lean, uses one controlled recovery step, catches quietly without collapse or extra step, holds the declared position, resets safely, and reports no stop symptom.","stopRules":["stop for pain, head-first fall risk, stumble, extra step, knee collapse, loss of balance, unsafe zone, or participant request","stop when one-step catch or hold quality cannot be restored with a lower threshold and full rest"],"coachInstructions":"Inspect the zone, declare lean/hold/side rules, demonstrate a one-step catch, observe from the side, balance lead sides, and stop before attempts become a sprint or fall drill.","athleteInstructions":"Lean as one line, catch with one step, freeze the split stance for the hold, reset, and do not sprint away.","expectedAdaptation":"Candidate initiation-control practice only; no guaranteed acceleration outcome is claimed.","equipmentRequired":["none"],"logistics":{"stationCapacity":1,"setupSeconds":30,"transitionSeconds":30,"clearanceRequired":true},"substitutionIds":[],"timeModel":{"setupSeconds":30,"perSetSeconds":75,"resetSeconds":45},"doseScaling":{"reduce":"reduce lean threshold, hold duration, or attempts; extend rest; or use another reviewed task after revalidation","doNotAutoProgress":"Do not add sprint distance, cueing, support removal, extra steps, resistanc